--
-- 转存表中的数据 `help`
--

INSERT INTO `help` (`id`, `title`, `content`, `markdown`, `class`, `add_time`, `ontop`, `sort`) VALUES
(1, 'ShadowsocksR', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 SSR 客户端，解压后以管理员身份运行 <code>ShadowsocksR-dotnet4.0.exe</code>。若系统提示需要安装 <code>.NET Framework</code>，请<a href=\"https://dotnet.microsoft.com/download/dotnet-framework/net472\" title=\"点此\">点此</a>访问微软官网下载安装。</p>\n<p><a href=\"/clients/ssr-win.7z\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击这个按钮 👇👇👇</p>\n<p><button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-ssr-2.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>再次右键点击小飞机，选择 “服务器订阅” > “更新SSR服务器订阅(不通过代理)”</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-ssr-3.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n<h2 id=\"h2-4-\"><a name=\"4.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>4.</h2><p>右键点击小飞机，选择 “服务器” > “Cool”，可随意切换节点。选择节点后即可正常使用。</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-ssr-4.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n', '## 1.\n下载 SSR 客户端，解压后以管理员身份运行 `ShadowsocksR-dotnet4.0.exe`。若系统提示需要安装 `.NET Framework`，请[点此](https://dotnet.microsoft.com/download/dotnet-framework/net472 \"点此\")访问微软官网下载安装。\n\n<a href=\"/clients/ssr-win.7z\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n## 2.\n点击这个按钮 👇👇👇\n\n<button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n![ssr](/theme/cool/img/tutorial/windows-ssr-2.jpg \"ssr\")\n\n## 3.\n再次右键点击小飞机，选择 “服务器订阅” > “更新SSR服务器订阅(不通过代理)”\n\n![ssr](/theme/cool/img/tutorial/windows-ssr-3.jpg \"ssr\")\n\n## 4.\n右键点击小飞机，选择 “服务器” > “Cool”，可随意切换节点。选择节点后即可正常使用。\n\n![ssr](/theme/cool/img/tutorial/windows-ssr-4.jpg \"ssr\")\n', 1, '2021-09-19 17:23:59', 0, 1),
(2, 'Clash for Windows', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 <code>Clash for Windows</code> 客户端。</p>\n<p>安装时请选择：为使用这台电脑的任何人安装（所有用户）</p>\n<p>运行时请右键 -> 以管理员身份运行</p>\n<p><a href=\"/clients/Clash-Windows.exe\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击这个按钮 👇👇👇</p>\n<p><button type=\"button\" class=\"btn btn-clash waves-effect waves-light\" onclick=\"importSublink(&#39;clash&#39;)\"><i class=\"cool-clash\"></i> 一键导入 Clash</button>\n\n</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-cfw-2.png\" alt=\"clashr\" title=\"clashr\"></p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>打开客户端的侧边栏的 <code>General</code>，勾选 <code>System Proxy</code> 即可启用。</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-cfw-3.png\" alt=\"clashr\" title=\"clashr\"></p>\n', '## 1.\n下载 `Clash for Windows` 客户端。\n\n安装时请选择：为使用这台电脑的任何人安装（所有用户）\n\n运行时请右键 -> 以管理员身份运行\n\n<a href=\"/clients/Clash-Windows.exe\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n## 2.\n点击这个按钮 👇👇👇\n<button type=\"button\" class=\"btn btn-clash waves-effect waves-light\" onclick=\"importSublink(\'clash\')\"><i class=\"cool-clash\"></i> 一键导入 Clash</button>\n\n![clashr](/theme/cool/img/tutorial/windows-cfw-2.png \"clashr\")\n\n## 3.\n打开客户端的侧边栏的 `General`，勾选 `System Proxy` 即可启用。\n\n![clashr](/theme/cool/img/tutorial/windows-cfw-3.png \"clashr\")\n', 1, '2021-09-22 00:14:37', 0, 0),
(3, 'Netch 游戏加速', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 <code>Netch</code> 客户端，解压后以管理员身份运行 <code>Netch.exe</code>。若系统提示需要安装 <code>.NET Framework</code>，请<a href=\"https://dotnet.microsoft.com/download/dotnet-framework/net472\" title=\"点此\">点此</a>访问微软官网下载安装。</p>\n<p><a href=\"/clients/Netch.7z\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>打开程序后，选中 “订阅” > “管理订阅链接”</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-netch-2.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>粘贴订阅链接到左下角的链接，备注填写为，点击添加，然后点击保存</p>\n<p><button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n</p>\n<p><button type=\"button\" class=\"btn btn-v2ray waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=3\"><i class=\"cool-v2rayng\"></i> 复制 V2ray 订阅</button>\n\n</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-netch-3.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n<h2 id=\"h2-4-\"><a name=\"4.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>4.</h2><p>如果需要加速的游戏不在列表里面，那么就选中 “模式” > “创建进程模式”</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-netch-4.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n<h2 id=\"h2-5-\"><a name=\"5.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>5.</h2><p>点击 “扫描” 选取你游戏安装目录后选择确定即可添加，点击保存即可选择应用此模式</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-netch-5.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n<h2 id=\"h2-6-\"><a name=\"6.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>6.</h2><p>最后选择模式，点击启动即可使用。</p>\n<p><img src=\"/theme/cool/img/tutorial/windows-netch-7.jpg\" alt=\"ssr\" title=\"ssr\"></p>\n', '## 1.\n下载 `Netch` 客户端，解压后以管理员身份运行 `Netch.exe`。若系统提示需要安装 `.NET Framework`，请[点此](https://dotnet.microsoft.com/download/dotnet-framework/net472 \"点此\")访问微软官网下载安装。\n\n<a href=\"/clients/Netch.7z\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n## 2.\n打开程序后，选中 “订阅” > “管理订阅链接”\n\n![ssr](/theme/cool/img/tutorial/windows-netch-2.jpg \"ssr\")\n\n## 3.\n粘贴订阅链接到左下角的链接，备注填写为，点击添加，然后点击保存\n\n<button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n<button type=\"button\" class=\"btn btn-v2ray waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=3\"><i class=\"cool-v2rayng\"></i> 复制 V2ray 订阅</button>\n\n![ssr](/theme/cool/img/tutorial/windows-netch-3.jpg \"ssr\")\n\n## 4.\n如果需要加速的游戏不在列表里面，那么就选中 “模式” > “创建进程模式”\n\n![ssr](/theme/cool/img/tutorial/windows-netch-4.jpg \"ssr\")\n\n## 5.\n点击 “扫描” 选取你游戏安装目录后选择确定即可添加，点击保存即可选择应用此模式\n\n![ssr](/theme/cool/img/tutorial/windows-netch-5.jpg \"ssr\")\n\n## 6.\n最后选择模式，点击启动即可使用。\n\n![ssr](/theme/cool/img/tutorial/windows-netch-7.jpg \"ssr\")\n', 1, '2021-09-19 17:24:32', 0, 1),
(4, 'Clash for Android', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 <code>Clash for Android</code> 客户端。</p>\n<p><a href=\"/clients/Clash-Android.apk\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击这个按钮 👇👇👇</p>\n<p><button type=\"button\" class=\"btn btn-clash waves-effect waves-light\" onclick=\"importSublink(&#39;clash&#39;)\"><i class=\"cool-clash\"></i>  一键导入托管配置到 Clash for Android</button>\n\n</p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>会到主界面，点击顶部灰色卡片，卡片颜色变成蓝色即代表代理已开启。</p>\n<p>开启后，可在第二个卡片 <code>Proxy</code> 里切换节点。</p>\n', '## 1.\n下载 `Clash for Android` 客户端。\n\n<a href=\"/clients/Clash-Android.apk\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n## 2.\n点击这个按钮 👇👇👇\n<button type=\"button\" class=\"btn btn-clash waves-effect waves-light\" onclick=\"importSublink(\'clash\')\"><i class=\"cool-clash\"></i>  一键导入托管配置到 Clash for Android</button>\n\n## 3.\n会到主界面，点击顶部灰色卡片，卡片颜色变成蓝色即代表代理已开启。\n\n开启后，可在第二个卡片 `Proxy` 里切换节点。\n', 2, '2021-09-22 00:14:12', 0, 0),
(5, 'ShadowsocksR', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 <code>SSR</code> 客户端。</p>\n<p><a href=\"/clients/ssr-android.apk\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>打开 <code>ShadowsocksR(R)</code> 点击左上角的<code>「ShadowsocksR」</code>进入配置文件管理页面。</p>\n<p>点击右下角的加号按钮，在弹出的选项中选择 <code>「添加/升级 SSR 订阅」</code>。</p>\n<p><button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n\n</p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>点击选择您需要的节点，随后往下划到功能设置处，点击<code>「路由」</code>将其更改为 <code>绕过局域网及中国大陆地址</code>。</p>\n<p>随后往上划到顶部，点击右上角小飞机即可成功连接。</p>\n', '## 1.\n下载 `SSR` 客户端。\n\n<a href=\"/clients/ssr-android.apk\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n## 2.\n打开 `ShadowsocksR(R)` 点击左上角的`「ShadowsocksR」`进入配置文件管理页面。\n\n点击右下角的加号按钮，在弹出的选项中选择 `「添加/升级 SSR 订阅」`。\n\n<button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n\n## 3.\n点击选择您需要的节点，随后往下划到功能设置处，点击`「路由」`将其更改为 `绕过局域网及中国大陆地址`。\n\n随后往上划到顶部，点击右上角小飞机即可成功连接。\n', 2, '2021-09-22 00:14:02', 0, 1),
(6, 'V2rayNG', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 <code>v2rayNG</code> 客户端。</p>\n<p><a href=\"/clients/v2rayng.apk\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>打开 <code>V2rayNG</code> 点击左上角的菜单图标打开侧边栏，随后点击 订阅设置。点击右上角的加号按钮，在新页面的备注中填写本站名称，地址输入框中粘贴订阅链接并点击右上角的 。</p>\n<p><button type=\"button\" class=\"btn btn-v2ray waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=3\"><i class=\"cool-v2rayng\"></i> 复制 V2ray 订阅</button>\n\n</p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>再次从侧边栏进入 <code>设置</code> 页面，点击 <code>路由模式</code> 将其更改为 <code>绕过局域网及大陆地址</code></p>\n<h2 id=\"h2-4-\"><a name=\"4.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>4.</h2><p>随后从侧边栏回到 <code>配置文件</code> 页面，点击右上角的省略号图标选择更新订阅。</p>\n<h2 id=\"h2-5-\"><a name=\"5.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>5.</h2><p>点击选择您需要的节点，点击右下角的按钮即可连接。</p>\n', '## 1.\n下载 `v2rayNG` 客户端。\n\n<a href=\"/clients/v2rayng.apk\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n## 2.\n打开 `V2rayNG` 点击左上角的菜单图标打开侧边栏，随后点击 订阅设置。点击右上角的加号按钮，在新页面的备注中填写本站名称，地址输入框中粘贴订阅链接并点击右上角的 。\n\n<button type=\"button\" class=\"btn btn-v2ray waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=3\"><i class=\"cool-v2rayng\"></i> 复制 V2ray 订阅</button>\n\n## 3.\n再次从侧边栏进入 `设置` 页面，点击 `路由模式` 将其更改为 `绕过局域网及大陆地址`\n\n## 4.\n随后从侧边栏回到 `配置文件` 页面，点击右上角的省略号图标选择更新订阅。\n\n## 5.\n点击选择您需要的节点，点击右下角的按钮即可连接。\n\n', 2, '2021-09-22 00:12:28', 0, 2),
(7, 'Shadowrocket', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>在 <code>App Store</code> 登录本站提供的美区 <code>Apple ID</code> 下载客户端。</p>\n<p>为了保护您的隐私，请勿在手机设置里直接登录，仅在 <code>App Store</code> 登录即可。</p>\n<p>购买会员计划后，点击这里访问<a href=\"/user/share-account\" title=\"共享账号\">共享账号</a>页面</p>\n<p><a href=\"https://apps.apple.com/us/app/shadowrocket/id932747118\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fab fa-apple\"></i> 打开 App Store 下载</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击这个按钮 👇👇👇，会自动跳转添加订阅。</p>\n<p><button type=\"button\" class=\"btn btn-shadowrocket waves-effect waves-light\" onclick=\"importSublink(&#39;shadowrocket&#39;)\"><i class=\"cool-shadowrocket\"></i> 一键导入 Shadowrocket 配置</button>\n\n</p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>点击底栏的配置，选择添加配置，粘贴配置链接，下载。</p>\n<p>随后点击 <code>远程文件</code> 中新增的配置文件地址，在弹出的菜单中选择第二个<code>「使用配置」</code>，此时 <code>APP</code> 会自动开始下载配置并应用配置。</p>\n<p>回到首页，点击进入<code>「全局路由」</code>将其更改为 <code>配置</code>。</p>\n<p><a href=\"##\" class=\"btn btn-icon icon-left btn-primary copy-text\" data-clipboard-text=\"https://raw.githubusercontent.com/Hackl0us/Surge-Rule-Snippets/master/LAZY_RULES/Shadowrocket.conf\"><i class=\"far fa-copy\"></i> 复制配置链接</a></p>\n<h2 id=\"h2-4-\"><a name=\"4.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>4.</h2><p>点击底栏的首页，随意选择一个节点，打开顶部的开关即可启用。</p>\n', '## 1.\n在 `App Store` 登录本站提供的美区 `Apple ID` 下载客户端。\n\n为了保护您的隐私，请勿在手机设置里直接登录，仅在 `App Store` 登录即可。\n\n购买会员计划后，点击这里访问[共享账号](/user/share-account \"共享账号\")页面\n\n<a href=\"https://apps.apple.com/us/app/shadowrocket/id932747118\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fab fa-apple\"></i> 打开 App Store 下载</a>\n\n## 2.\n点击这个按钮 👇👇👇，会自动跳转添加订阅。\n\n<button type=\"button\" class=\"btn btn-shadowrocket waves-effect waves-light\" onclick=\"importSublink(\'shadowrocket\')\"><i class=\"cool-shadowrocket\"></i> 一键导入 Shadowrocket 配置</button>\n\n## 3.\n点击底栏的配置，选择添加配置，粘贴配置链接，下载。\n\n随后点击 `远程文件` 中新增的配置文件地址，在弹出的菜单中选择第二个`「使用配置」`，此时 `APP` 会自动开始下载配置并应用配置。\n\n回到首页，点击进入`「全局路由」`将其更改为 `配置`。\n\n<a href=\"##\" class=\"btn btn-icon icon-left btn-primary copy-text\" data-clipboard-text=\"https://raw.githubusercontent.com/Hackl0us/Surge-Rule-Snippets/master/LAZY_RULES/Shadowrocket.conf\"><i class=\"far fa-copy\"></i> 复制配置链接</a>\n\n## 4.\n点击底栏的首页，随意选择一个节点，打开顶部的开关即可启用。\n\n', 3, '2021-09-22 00:19:53', 0, 0),
(8, 'Quantumult', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>在 <code>App Store</code> 登录本站提供的美区 <code>Apple ID</code> 下载客户端。</p>\n<p>为了保护您的隐私，请勿在手机设置里直接登录，仅在 <code>App Store</code> 登录即可。</p>\n<p>购买会员计划后，点击这里访问<a href=\"/user/share-account\" title=\"共享账号\">共享账号</a>页面</p>\n<p><a href=\"https://itunes.apple.com/us/app/quantumult/id1252015438?ls=1&mt=8\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fab fa-apple\"></i> 打开 App Store 下载</a></p>\n<p><img src=\"/theme/cool/img/tutorial/ios-quantumult-1.png\" alt=\"Quantumult\" title=\"Quantumult\"></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击这个按钮 👇👇👇，如图所示，<code>Server</code> 不为0就是导入成功了。</p>\n<p><button type=\"button\" class=\"btn btn-quantumult waves-effect waves-light\" onclick=\"importSublink(&#39;quantumult&#39;)\"><i class=\"cool-quantumult\"></i> 一键导入 Quantumult 配置</button>\n\n</p>\n<p><img src=\"/theme/cool/img/tutorial/ios-quantumult-2.png\" alt=\"Quantumult\" title=\"Quantumult\"></p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>选择客户端底栏的主页，打开顶部的开关即可启用。<br><img src=\"/theme/cool/img/tutorial/ios-quantumult-3.png\" alt=\"Quantumult\" title=\"Quantumult\"></p>\n', '## 1.\n在 `App Store` 登录本站提供的美区 `Apple ID` 下载客户端。\n\n为了保护您的隐私，请勿在手机设置里直接登录，仅在 `App Store` 登录即可。\n\n购买会员计划后，点击这里访问[共享账号](/user/share-account \"共享账号\")页面\n\n<a href=\"https://itunes.apple.com/us/app/quantumult/id1252015438?ls=1&mt=8\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fab fa-apple\"></i> 打开 App Store 下载</a>\n\n![Quantumult](/theme/cool/img/tutorial/ios-quantumult-1.png \"Quantumult\")\n\n## 2.\n点击这个按钮 👇👇👇，如图所示，`Server` 不为0就是导入成功了。\n\n<button type=\"button\" class=\"btn btn-quantumult waves-effect waves-light\" onclick=\"importSublink(\'quantumult\')\"><i class=\"cool-quantumult\"></i> 一键导入 Quantumult 配置</button>\n\n![Quantumult](/theme/cool/img/tutorial/ios-quantumult-2.png \"Quantumult\")\n\n## 3.\n选择客户端底栏的主页，打开顶部的开关即可启用。\n![Quantumult](/theme/cool/img/tutorial/ios-quantumult-3.png \"Quantumult\")\n\n', 3, '2021-09-22 00:23:48', 0, 1),
(9, 'ClashX', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 <code>ClashX</code> 客户端，安装后运行 <code>ClashX</code></p>\n<p><a href=\"/clients/ClashX.dmg\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<p><img src=\"/theme/cool/img/tutorial/mac-clashx-1.png\"\" alt=\"clashx\" title=\"clashx\"></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击这个按钮 👇👇👇</p>\n<p><button type=\"button\" class=\"btn btn-clash waves-effect waves-light\" onclick=\"importSublink(&#39;clash&#39;)\"><i class=\"cool-clash\"></i>  一键导入托管配置到 ClashX</button>\n\n</p>\n<p><img src=\"/theme/cool/img/tutorial/mac-clashx-2.png\"\" alt=\"clashx\" title=\"clashx\"></p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>点击 ClashX 图标，勾选 <code>设置为系统代理</code> 即可启用。</p>\n<p><img src=\"/theme/cool/img/tutorial/mac-clashx-3.png\"\" alt=\"clashx\" title=\"clashx\"></p>\n', '## 1.\n下载 `ClashX` 客户端，安装后运行 `ClashX`\n\n<a href=\"/clients/ClashX.dmg\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n![clashx](/theme/cool/img/tutorial/mac-clashx-1.png\" \"clashx\")\n\n## 2.\n点击这个按钮 👇👇👇\n\n<button type=\"button\" class=\"btn btn-clash waves-effect waves-light\" onclick=\"importSublink(\'clash\')\"><i class=\"cool-clash\"></i>  一键导入托管配置到 ClashX</button>\n\n![clashx](/theme/cool/img/tutorial/mac-clashx-2.png\" \"clashx\")\n\n## 3.\n点击 ClashX 图标，勾选 `设置为系统代理` 即可启用。\n\n\n![clashx](/theme/cool/img/tutorial/mac-clashx-3.png\" \"clashx\")\n', 4, '2021-09-22 00:27:26', 0, 0),
(10, 'ShawdowsockX-NG-R8 ', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>下载 <code>ShawdowsockX-NG-R8</code> 客户端，安装后运行。</p>\n<p><a href=\"/clients/ssr-mac.dmg\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击屏幕右上角小飞机图标，选择 <code>服务器</code> > <code>编辑订阅</code>，然后点击左下角 <code>+</code>号，粘贴订阅地址，组名填写为 <code>Cool</code>，最后点击 <code>OK</code></p>\n<p><button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n</p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>再次点击屏幕右上角小飞机图标，选择 <code>服务器</code> > <code>手动更新订阅</code></p>\n<h2 id=\"h2-4-\"><a name=\"4.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>4.</h2><p>再次点击屏幕右上角小飞机图标，选择 <code>打开Shadowsocks</code> 即可使用。</p>\n', '## 1.\n下载 `ShawdowsockX-NG-R8` 客户端，安装后运行。\n\n<a href=\"/clients/ssr-mac.dmg\" class=\"btn btn-icon icon-left btn-primary\" target=\"blank\"><i class=\"fas fa-download\"></i> 下载客户端</a>\n\n## 2.\n点击屏幕右上角小飞机图标，选择 `服务器` > `编辑订阅`，然后点击左下角 `+`号，粘贴订阅地址，组名填写为 `Cool`，最后点击 `OK`\n\n<button type=\"button\" class=\"btn btn-ssr waves-effect waves-light copy-text\" data-clipboard-text=\"{$subUrl}{$ssr_sub_token}?sub=1\"><i class=\"cool-ssr\"></i> 复制 SSR 订阅</button>\n\n## 3.\n再次点击屏幕右上角小飞机图标，选择 `服务器` > `手动更新订阅`\n\n## 4.\n再次点击屏幕右上角小飞机图标，选择 `打开Shadowsocks` 即可使用。\n\n\n', 4, '2021-09-22 00:31:40', 0, 0),
(11, 'Clash', '<h2 id=\"h2-1-\"><a name=\"1.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>1.</h2><p>执行 <code>cd && mkdir clash</code> 在用户目录下创建 <code>clash</code> 文件夹。</p>\n<p>下载适合的 <code>Clash</code> 二进制文件并解压重命名为 <code>clash</code></p>\n<p>一般个人的64位电脑下载 <code>clash-linux-amd64.tar.gz</code> 即可。</p>\n<p><a href=\"https://github.com/Dreamacro/clash/releases\" class=\"btn btn-icon icon-left btn-danger\" target=\"blank\"><i class=\"fab fa-github\"></i> 下载客户端</a></p>\n<p><img src=\"/theme/cool/img/tutorial/windows-cfw-1.png\" alt=\"clash\" title=\"clash\"></p>\n<h2 id=\"h2-2-\"><a name=\"2.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>2.</h2><p>点击这个按钮 👇👇👇</p>\n<p>在终端 <code>cd</code> 到 <code>Clash</code> 二进制文件所在的目录，执行 <code>wget -O config.yml {$subUrl}{$ssr_sub_token}?clash=1&log-level=info</code> 下载 <code>Clash</code> 配置文件</p>\n<p><a href=\"##\" class=\"btn btn-icon icon-left btn-danger copy-text\" data-clipboard-text=\"wget -O config.yml {$subUrl}{$ssr_sub_token}?clash=1&log-level=info\"><i class=\"cool-clash\"></i> 复制 wget 命令</a></p>\n<p><img src=\"/theme/cool/img/tutorial/linux-clash-2.jpg\" alt=\"clash\" title=\"clash\"></p>\n<h2 id=\"h2-3-\"><a name=\"3.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>3.</h2><p>执行 <code>./clash -d .</code> 即可启动 Clash，同时启动 HTTP 代理和 Socks5 代理。</p>\n<p>如提示权限不足，请执行 <code>chmod +x clash</code></p>\n<p><img src=\"/theme/cool/img/tutorial/linux-clash-3.jpg\" alt=\"clash\" title=\"clash\"></p>\n<h2 id=\"h2-4-\"><a name=\"4.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>4.</h2><p>访问 <code>Clash Dashboard</code> 可以进行切换节点、测延迟等操作。</p>\n<p>Host: <code>127.0.0.1</code>，端口: <code>9090</code></p>\n<p><img src=\"/theme/cool/img/tutorial/linux-clash-4.jpg \"clash\"\" alt=\"clash\" width=\"800\" height=\"450\"></p>\n<h2 id=\"h2-5-\"><a name=\"5.\" class=\"reference-link\"></a><span class=\"header-link octicon octicon-link\"></span>5.</h2><p>以 <code>Ubuntu 19.04</code> 为例，打开系统设置，选择网络，点击网络代理右边的 ⚙ 按钮，选择手动，填写 <code>HTTP</code> 和 <code>HTTPS</code> 代理为 <code>127.0.0.1:7890</code>，填写 <code>Socks</code> 主机为 <code>127.0.0.1:7891</code>，即可启用系统代理。</p>\n<p><img src=\"/theme/cool/img/tutorial/linux-clash-5.jpg\" alt=\"clash\" title=\"clash\"></p>\n', '## 1.\n执行 `cd && mkdir clash` 在用户目录下创建 `clash` 文件夹。\n\n下载适合的 `Clash` 二进制文件并解压重命名为 `clash`\n\n一般个人的64位电脑下载 `clash-linux-amd64.tar.gz` 即可。\n\n<a href=\"https://github.com/Dreamacro/clash/releases\" class=\"btn btn-icon icon-left btn-danger\" target=\"blank\"><i class=\"fab fa-github\"></i> 下载客户端</a>\n\n![clash](/theme/cool/img/tutorial/windows-cfw-1.png \"clash\")\n\n## 2.\n点击这个按钮 👇👇👇\n\n在终端 `cd` 到 `Clash` 二进制文件所在的目录，执行 `wget -O config.yml {$subUrl}{$ssr_sub_token}?clash=1&log-level=info` 下载 `Clash` 配置文件\n\n<a href=\"##\" class=\"btn btn-icon icon-left btn-danger copy-text\" data-clipboard-text=\"wget -O config.yml {$subUrl}{$ssr_sub_token}?clash=1&log-level=info\"><i class=\"cool-clash\"></i> 复制 wget 命令</a>\n\n![clash](/theme/cool/img/tutorial/linux-clash-2.jpg \"clash\")\n\n## 3.\n执行 `./clash -d .` 即可启动 Clash，同时启动 HTTP 代理和 Socks5 代理。\n\n如提示权限不足，请执行 `chmod +x clash`\n\n![clash](/theme/cool/img/tutorial/linux-clash-3.jpg \"clash\")\n\n## 4.\n访问 `Clash Dashboard` 可以进行切换节点、测延迟等操作。\n\nHost: `127.0.0.1`，端口: `9090`\n\n![clash](/theme/cool/img/tutorial/linux-clash-4.jpg \"clash\"=800x450)\n## 5.\n以 `Ubuntu 19.04` 为例，打开系统设置，选择网络，点击网络代理右边的 ⚙ 按钮，选择手动，填写 `HTTP` 和 `HTTPS` 代理为 `127.0.0.1:7890`，填写 `Socks` 主机为 `127.0.0.1:7891`，即可启用系统代理。\n\n![clash](/theme/cool/img/tutorial/linux-clash-5.jpg \"clash\")', 5, '2021-09-22 00:39:50', 0, 0);

--
-- 转储表的索引
--

--
-- 表的索引 `help`
--
ALTER TABLE `help`
  ADD PRIMARY KEY (`id`) USING BTREE;

--
-- 在导出的表使用AUTO_INCREMENT
--

--
-- 使用表AUTO_INCREMENT `help`
--
ALTER TABLE `help`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=14;
COMMIT;

/*!40101 SET CHARACTER_SET_CLIENT=@OLD_CHARACTER_SET_CLIENT */;
/*!40101 SET CHARACTER_SET_RESULTS=@OLD_CHARACTER_SET_RESULTS */;
/*!40101 SET COLLATION_CONNECTION=@OLD_COLLATION_CONNECTION */;
